\version "2.27.2"
% automatically converted by musicxml2ly from 33da-Spanners-OctaveShifts-before.xml
\pointAndClickOff

\header {
  "id: software" = Finale
  texidoc = "All types of octave shifts (15ma on the third eighth note, 15mb on
    the fourth and fifth, 8va on the sixth and seventh, and 8vb on the last two
    16th notes). This test file positions <octave-shift type=\"stop\"> before
    the associated note, as expected in MusicXML import of Finale, for example.
    Consequently, it contains ‘Finale’ as the <software> tag.

    Note that the end of the last octave shift is anchored at the following bar
    line."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative a' {
  \clef "treble" \time 4/4 \key c \major a8 [ c8 \ottava #2 a''8 \ottava #0
  \ottava #-2 c,,,,8 ] b8 [ \ottava #0 \ottava #1 a'''8 ] a8 [ \ottava #0
  \ottava #-1 b,,16 c16 ] \ottava #0 | % 1
  c'1 \bar "|."
}


% The score definition
